CREATE TABLE public.coupons ( id UUID DEFAULT uuid_generate_v4() PRIMARY KEY, code VARCHAR(50) UNIQUE NOT NULL, discount_percentage NUMERIC DEFAULT 0, advertiser_name VARCHAR(255), is_active BOOLEAN DEFAULT true, usage_count INTEGER DEFAULT 0, created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) ); ALTER TABLE public.custom_requests ADD COLUMN coupon_id UUID REFERENCES public.coupons(id);
